    public func hash(into hasher: inout Hasher) {
        hasher.combine(cacheMaxBytes)
        hasher.combine(spillwayMaxBytes)
        hasher.combine(drainInsertion)
        hasher.combine(createIfMissing)
        hasher.combine(readOnly)
        hasher.combine(superblockCount)
        hasher.combine(encryptionKey)
        hasher.combine(argon2Params)
    }
}



