        self.handleCount = handleCount
        self.totalPages = totalPages
        self.fileSizeBytes = fileSizeBytes
        self.spillwayLogicalBytes = spillwayLogicalBytes
        self.spillwayMaxBytes = spillwayMaxBytes
    }
}

