    public static func ==(lhs: Stats, rhs: Stats) -> Bool {
        if lhs.handleCount != rhs.handleCount {
            return false
        }
        if lhs.totalPages != rhs.totalPages {
            return false
        }
        if lhs.fileSizeBytes != rhs.fileSizeBytes {
            return false
