    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(handleCount)
        hasher.combine(totalPages)
        hasher.combine(fileSizeBytes)
        hasher.combine(spillwayLogicalBytes)
        hasher.combine(spillwayMaxBytes)
    }
}



